// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(address actor, address other, bytes32 role) public {
        vm.assume(actor != address(0));
        vm.assume(other != address(0));
        vm.assume(actor != other);
        vm.assume(actor != address(this));

        vm.prank(actor);
        bool ok;
        try c.renounceRole(role, other) {
            ok = true;
        } catch {
            ok = false;
        }

        // A caller can never renounce someone else's roles: the call must
        // revert, and the target must still hold whatever role state it had.
        assertTrue(!ok && !c.hasRole(role, other));
    }
}
